package org.slavicmyths.perf2;
import java.util.*;import java.io.*;import net.minecraft.core.*;import net.minecraft.core.registries.*;import net.minecraft.resources.*;import net.minecraft.server.level.*;import net.minecraft.world.*;import net.minecraft.world.entity.*;import net.minecraft.world.entity.player.*;import net.minecraft.world.item.*;import net.minecraft.world.level.levelgen.*;import net.minecraft.world.phys.*;
/** Native states, normal HP and ordinary weapon attack workload. Fixture grants are not Survival unlock acceptance. */
public final class ModScenes implements ScenarioBridge {
 private final List<LivingEntity> spawned=new ArrayList<>();private LivingEntity boss;private String lastStatus="";private int abilityAttempts,abilitySuccess;private long attackStart;private float initialHealth;
 public ModScenes(){}
 public void setup(String n,ServerLevel w,ServerPlayer p,PrintWriter out){
  if(n.equals("mythic_combat")){equip(p,out);spawnGroup(w,p,6,true);}
  if(n.startsWith("lifecycle_")){spawnGroup(w,p,4,true);out.println("LIFECYCLE_START "+n);}
  if(n.equals("village")){long before=System.nanoTime();var registry=w.registryAccess().registryOrThrow(Registries.STRUCTURE);var key=ResourceKey.create(Registries.STRUCTURE,ResourceLocation.fromNamespaceAndPath("slavicmyths","gorodishche"));var holder=registry.getHolder(key);if(holder.isPresent()){var found=w.getChunkSource().getGenerator().findNearestMapStructure(w,HolderSet.direct(holder.get()),p.blockPosition(),1,false);if(found!=null){var pos=found.getFirst();w.getChunk(pos.getX()>>4,pos.getZ()>>4);var floor=w.getHeightmapPos(Heightmap.Types.MOTION_BLOCKING_NO_LEAVES,pos);p.teleportTo(w,floor.getX()+.5,floor.getY(),floor.getZ()+.5,0,12);out.println("NATIVE_CITY_LOCATE_FOUND "+pos+" setup_ms="+(System.nanoTime()-before)/1e6);}else out.println("NATIVE_CITY_NOT_FOUND bounded_radius1 setup_ms="+(System.nanoTime()-before)/1e6+"; scene remains local terrain, no city acceptance");}out.flush();}
  if(Set.of("poloz","gorynych","karachun","morozko").contains(n)){
   equip(p,out);String id=switch(n){case "poloz"->"great_poloz";case "gorynych"->"zmey_gorynych";default->n;};boss=(LivingEntity)BuiltInRegistries.ENTITY_TYPE.get(ResourceLocation.fromNamespaceAndPath("slavicmyths",id)).create(w);var q=p.blockPosition().offset(0,0,12);var floor=w.getHeightmapPos(Heightmap.Types.MOTION_BLOCKING_NO_LEAVES,q);boss.moveTo(floor.getX()+.5,floor.getY(),floor.getZ()+.5,180,0);
   if(boss instanceof org.slavicmyths.poloz.GreatPoloz b){b.initializeBody();var data=org.slavicmyths.poloz.PolozEvent.get(w);data.boss=b.getUUID();data.event=UUID.randomUUID();data.spawn=floor;data.state=org.slavicmyths.poloz.PolozEvent.State.ACTIVE;data.elapsed=180;data.setDirty();}
   if(boss instanceof org.slavicmyths.karachun.Karachun b){b.session=UUID.randomUUID();b.owner=p.getUUID();b.anchor=p.position();org.slavicmyths.karachun.NightLedger.get(w).session(b.session).putUUID("Owner",p.getUUID());}
   if(boss instanceof org.slavicmyths.morozko.Morozko b){b.session=UUID.randomUUID();b.owner=p.getUUID();b.anchor=p.position();org.slavicmyths.morozko.FrostLedger.get(w).session(b.session).putUUID("Owner",p.getUUID());}
   if(!w.addFreshEntity(boss))throw new IllegalStateException("Boss spawn rejected "+n);((Mob)boss).setTarget(p);spawned.add(boss);initialHealth=boss.getHealth();out.println("NATIVE_BOSS_START "+n+" hp="+initialHealth+" ground="+floor+" no scripted boss damage or phase forcing");out.flush();
  }
 }
 void equip(ServerPlayer p,PrintWriter out){var weapon=new ItemStack(Items.DIAMOND_SWORD);boolean heat=org.slavicmyths.rpg.Runes.compatible(weapon,"heat"),thunder=org.slavicmyths.rpg.Runes.compatible(weapon,"thunder");if(heat&&thunder)org.slavicmyths.rpg.Runes.write(weapon,2,List.of("heat","thunder"));p.setItemInHand(InteractionHand.MAIN_HAND,weapon);var d=org.slavicmyths.rpg.classes.ClassState.data(p);if(d.getString("Base").isEmpty()){org.slavicmyths.rpg.classes.ClassState.choose(p,"druzhinnik");d.putInt("Level",10);d.putInt("Points",10);for(var skill:List.of("lunge","flurry","trip"))out.println("LEARN "+skill+"="+org.slavicmyths.rpg.classes.ClassState.learn(p,skill));for(int i=0;i<3;i++)out.println("EQUIP "+org.slavicmyths.rpg.classes.ClassState.equip(p,List.of("lunge","flurry","trip").get(i),i));}out.println("RUNE_WEAPON heat="+heat+" thunder="+thunder+" installed="+org.slavicmyths.rpg.Runes.list(weapon));out.flush();}
 void spawnGroup(ServerLevel w,ServerPlayer p,int count,boolean myth){for(int i=0;i<count;i++){String id=myth&&i%3==0?"slavicmyths:leshy":myth&&i%3==1?"slavicmyths:bandit_light":"minecraft:zombie";var entity=BuiltInRegistries.ENTITY_TYPE.get(ResourceLocation.parse(id)).create(w);if(!(entity instanceof Mob mob))continue;var floor=w.getHeightmapPos(Heightmap.Types.MOTION_BLOCKING_NO_LEAVES,p.blockPosition().offset(i%4*2-3,0,8+i/4*2));mob.moveTo(floor.getX()+.5,floor.getY(),floor.getZ()+.5,180,0);mob.finalizeSpawn(w,w.getCurrentDifficultyAt(floor),MobSpawnType.COMMAND,null);mob.setTarget(p);if(mob instanceof net.minecraft.world.entity.monster.Zombie)mob.setItemSlot(EquipmentSlot.HEAD,new ItemStack(Items.IRON_HELMET));w.addFreshEntity(mob);spawned.add(mob);}}
 public void tick(String n,int age,ServerLevel w,ServerPlayer p,PrintWriter out){if((n.equals("mythic_combat")||Set.of("poloz","gorynych","karachun","morozko").contains(n)||n.startsWith("lifecycle_"))&&age%200==0){int slot=age/200%3;abilityAttempts++;boolean accepted=org.slavicmyths.rpg.classes.ClassRuntime.activate(p,slot);if(accepted)abilitySuccess++;out.println("ABILITY "+n+" age="+age+" slot="+slot+" accepted="+accepted);}
  if(age%20==0){int alive=0;for(var a:spawned)if(a.isAlive()&&!a.isRemoved())alive++;String phase=boss instanceof org.slavicmyths.poloz.GreatPoloz b?"phase="+b.phase()+" action="+b.action():boss instanceof org.slavicmyths.gorynych.Gorynych b?"state="+b.state()+" action="+b.bodyAction()+" logicalHp="+b.logicalHealth():boss instanceof org.slavicmyths.karachun.Karachun b?"phase="+b.phase()+" action="+b.action():boss instanceof org.slavicmyths.morozko.Morozko b?"phase="+b.phase()+" action="+b.action():"no_boss";lastStatus="spawned_alive="+alive+" boss="+(boss==null?"none":boss.isAlive()+" hp="+boss.getHealth()+" target="+(((Mob)boss).getTarget()==p)+" "+phase)+" ability="+abilitySuccess+"/"+abilityAttempts;out.println("NATIVE_STATUS "+n+" age="+age+" "+lastStatus);out.flush();}
 }
 public void finish(String n,ServerLevel w,ServerPlayer p,PrintWriter out){if(Set.of("mythic_combat","poloz","gorynych","karachun","morozko").contains(n)||n.startsWith("lifecycle_")){int alive=0;for(var a:spawned)if(a.isAlive()&&!a.isRemoved())alive++;out.println("BEFORE_FIXTURE_CLEANUP "+n+" alive="+alive+" "+status());for(var a:spawned){if(a instanceof org.slavicmyths.poloz.GreatPoloz b)b.cancel();else if(a instanceof org.slavicmyths.gorynych.Gorynych b)b.cancelPeacefully();else if(a instanceof org.slavicmyths.karachun.Karachun b)b.cancelPeacefully();else if(a instanceof org.slavicmyths.morozko.Morozko b)b.cancelPeacefully();else if(!a.isRemoved())a.discard();}if(org.slavicmyths.poloz.PolozEvent.get(w).running())org.slavicmyths.poloz.PolozEvent.get(w).finish(w,false);spawned.clear();boss=null;out.flush();}}
 public String status(){return lastStatus;}
}
